    <div className="chart-grid"><Panel title="Discovery activity" subtitle="PII findings across your connected sources" action={<button className="select-chip">Last 7 days <ChevronDown size={13}/></button>}><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><AreaChart data={activityData} margin={{ top: 10, right: 8, bottom: 0, left: -18 }}><defs><linearGradient id="blueFade" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#3478f6" stopOpacity={0.2}/><stop offset="100%" stopColor="#3478f6" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="#eef1f5" vertical={false}/><XAxis dataKey="day" axisLine={false} tickLine={false} tick={{ fill: "#8b95a5", fontSize: 11 }}/><YAxis axisLine={false} tickLine={false} tick={{ fill: "#8b95a5", fontSize: 11 }}/><Tooltip contentStyle={{ border: "1px solid #edf0f4", borderRadius: 10, fontSize: 12 }}/><Area type="monotone" dataKey="findings" stroke="#3478f6" strokeWidth={2.5} fill="url(#blueFade)"/></AreaChart></ResponsiveContainer></div></Panel>
      <Panel title="PII by category" subtitle="3,842 total findings"><div className="donut-layout"><div className="donut"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={categoryData} dataKey="value" nameKey="name" innerRadius={48} outerRadius={65} paddingAngle={4} stroke="none">{categoryData.map((x) => <PieCell key={x.name} fill={x.color}/>)}</Pie><Tooltip/></PieChart></ResponsiveContainer><div className="donut-label"><strong>3,842</strong><span>findings</span></div></div><div className="legend">{categoryData.map(d=><div className="legend-row" key={d.name}><span className="legend-dot" style={{background:d.color}}/>{d.name}<strong>{d.value}%</strong></div>)}</div></div></Panel></div>
